import type { BoardManifest } from '@learn/lesson-runtime';
// Generated by tools/build-boards.mjs from every board folder (id -> content hash, manifest).
import editions from './editions.generated.json';

type Edition = { hash: string; manifest: BoardManifest };
const all = editions as unknown as Record<string, Edition>;

/** Board manifests by id, for ReadingLesson's `boards` prop. */
export const boardManifests: Readonly<Record<string, BoardManifest>> = Object.fromEntries(
  Object.entries(all).map(([id, edition]) => [id, edition.manifest]),
);

/** The board origin: a separate site, never the app's own (docs/boards.md). */
export function boardOrigin() {
  const configured = import.meta.env.VITE_BOARD_ORIGIN as string | undefined;
  if (configured) return configured.replace(/\/$/, '');
  const local = ['127.0.0.1', 'localhost'].includes(location.hostname);
  return local ? 'http://127.0.0.1:5174' : 'https://new-learn-boards.pages.dev';
}

/** The immutable address of a board edition, or null for an unknown board. */
export function boardUrl(id: string) {
  const edition = all[id];
  return edition ? `${boardOrigin()}/e/${edition.hash}/index.html` : null;
}

export function boardEdition(id: string): Edition | null {
  return all[id] ?? null;
}
